import Foundation

/// The C runtime behind SwiftUI-style apps: a view tree built each frame by generated code, then
/// laid out (stacks, padding, frames, flexible shapes and spacers), hit-tested and drawn.
nonisolated enum WuiRuntime {
    static let header = #"""
    /* wui.h: generated by Revolution Editor. Do not edit; changes are overwritten on build. */
    #ifndef WUI_H
    #define WUI_H

    #define WUI_INF 1e9f

    /* Alignment codes: row-major 3x3 (0 top/leading, 1 centre, 2 bottom/trailing): code = v * 3 + h. */
    #define WUI_CENTER 4

    void wui_begin(void);
    void wui_finish(void);                                  /* lay out, handle input, draw */

    /* Containers: axis 0 = VStack, 1 = HStack, 2 = ZStack. Close each with wui_end(). */
    void wui_begin_stack(int axis, int align, float spacing);
    void wui_begin_button(void (*action)(void *), void *ctx);
    void wui_end(void);

    /* Views */
    void wui_text(const char *s);
    void wui_image(int sprite);
    void wui_spacer(void);
    void wui_divider(void);
    void wui_shape(int kind, float radius);                 /* 0 rectangle, 1 rounded, 2 circle, 3 capsule */
    void wui_color(int r, int g, int b, int a);
    void wui_toggle(const char *label, int *value);
    void wui_slider(double *value, double lo, double hi);
    void wui_progress(double value);

    /* Modifiers: they wrap the view that was just added. */
    void wui_padding(float top, float right, float bottom, float left);
    void wui_frame(float w, float h, float minw, float maxw, float minh, float maxh, int align);   /* -1 = unset */
    void wui_background(int r, int g, int b, int a);
    void wui_foreground(int r, int g, int b, int a);
    void wui_font(int size, int bold);
    void wui_opacity(float o);
    void wui_offset(float x, float y);
    void wui_corner(float r);
    void wui_border(int r, int g, int b, int a, float width);
    void wui_on_tap(void (*action)(void *), void *ctx);
    void wui_long_press(void (*action)(void *), void *ctx, int frames);   /* runs once the A button has been held that long */
    void wui_underline(void);
    void wui_overlay(int r, int g, int b, int a);               /* a colour drawn over the view */
    void wui_shadow(int r, int g, int b, int a, float dx, float dy);
    void wui_position(float x, float y);                        /* centre the view at x, y in its parent */
    void wui_disabled(int disabled);
    void wui_resizable(int fit);
    void wui_line_limit(int n);
    void wui_button_plain(void);

    #endif

    """#

    static let source = #"""
    /* wui.c: generated by Revolution Editor. Do not edit; changes are overwritten on build. */
    #include <math.h>
    #include <stdlib.h>
    #include <string.h>
    #include "wiiui.h"
    #include "wui.h"

    enum { K_TEXT, K_IMAGE, K_SPACER, K_DIVIDER, K_SHAPE, K_COLOR, K_STACK, K_PADDING, K_FRAME, K_BACKGROUND, K_FOREGROUND,
           K_FONT, K_OPACITY, K_OFFSET, K_CORNER, K_BORDER, K_BUTTON, K_TAP, K_TOGGLE, K_SLIDER, K_PROGRESS };

    typedef struct wui_node wui_node;
    struct wui_node {
        int kind;
        wui_node *first, *last, *next, *prev, *parent;
        const char *text;
        float a[6];
        int i[4];
        unsigned char c[4];
        void (*action)(void *);
        void *ctx;
        int *flag;
        double *dval, lo, hi;
        float x, y, w, h;               /* final rectangle, relative to the parent's origin */
        float cpw, cph, cw, ch;         /* cached measurement: proposal and result */
        float ideal;                    /* scratch for stacks: ideal main-axis size */
        int flexmain;                   /* scratch for stacks: flexible along the main axis */
        unsigned char cvalid, cflexw, cflexh, interactive, disabled;
    };

    typedef struct { int font; int bold; unsigned char fg[4]; float opacity; float corner; int underline; } style;

    #define MAX_NODES 900
    static wui_node *pool;
    static int pool_n;
    static wui_node *root, *cur;
    static float last_px = -1, last_py = -1;
    static int focus = 0, controller = 0;
    static wui_node *hot = NULL, *pressed_node = NULL, *hold_node = NULL;
    static int hold_frames = 0;

    static float fmin2(float a, float b) { return a < b ? a : b; }
    static float fmax2(float a, float b) { return a > b ? a : b; }
    static float clampf(float v, float lo, float hi) { return v < lo ? lo : v > hi ? hi : v; }

    static wui_node *new_node(int kind) {
        if (pool_n >= MAX_NODES) exit(1);
        wui_node *n = &pool[pool_n++];
        memset(n, 0, sizeof *n);
        n->kind = kind;
        return n;
    }

    static void append(wui_node *parent, wui_node *n) {
        n->parent = parent;
        n->prev = parent->last;
        if (parent->last) parent->last->next = n; else parent->first = n;
        parent->last = n;
    }

    void wui_begin(void) {
        pool = (wui_node *)wiiui_arena_alloc(MAX_NODES * sizeof(wui_node));
        pool_n = 0;
        root = new_node(K_STACK);       /* invisible ZStack holding the root view */
        root->i[0] = 2; root->i[1] = 4;
        cur = root;
    }

    /* ---- building ---- */
    static wui_node *leaf(int kind) { wui_node *n = new_node(kind); append(cur, n); return n; }

    void wui_begin_stack(int axis, int align, float spacing) {
        wui_node *n = leaf(K_STACK);
        n->i[0] = axis; n->i[1] = align; n->a[0] = spacing;
        cur = n;
    }
    void wui_begin_button(void (*action)(void *), void *ctx) {
        wui_node *n = leaf(K_BUTTON);
        n->action = action; n->ctx = ctx; n->interactive = 1;
        cur = n;
    }
    void wui_end(void) { if (cur->parent) cur = cur->parent; }

    static const char *copy_text(const char *s) {
        size_t n = strlen(s) + 1;
        char *p = (char *)wiiui_arena_alloc((unsigned)n);
        memcpy(p, s, n);
        return p;
    }

    void wui_text(const char *s) { wui_node *n = leaf(K_TEXT); n->text = copy_text(s); n->i[2] = 0; }
    void wui_image(int sprite) { wui_node *n = leaf(K_IMAGE); n->i[0] = sprite; }
    void wui_spacer(void) { leaf(K_SPACER); }
    void wui_divider(void) { leaf(K_DIVIDER); }
    void wui_shape(int kind, float radius) { wui_node *n = leaf(K_SHAPE); n->i[0] = kind; n->a[0] = radius; }
    void wui_color(int r, int g, int b, int a) { wui_node *n = leaf(K_COLOR); n->c[0] = r; n->c[1] = g; n->c[2] = b; n->c[3] = a; }
    void wui_toggle(const char *label, int *value) { wui_node *n = leaf(K_TOGGLE); n->text = copy_text(label); n->flag = value; n->interactive = 1; }
    void wui_slider(double *value, double lo, double hi) { wui_node *n = leaf(K_SLIDER); n->dval = value; n->lo = lo; n->hi = hi; n->interactive = 1; }
    void wui_progress(double value) { wui_node *n = leaf(K_PROGRESS); n->lo = value; }

    /* Wraps the last view in `cur` in a new modifier node. */
    static wui_node *wrap(int kind) {
        wui_node *child = cur->last;
        if (!child) return NULL;
        wui_node *w = new_node(kind);
        w->parent = cur;
        w->prev = child->prev;
        if (child->prev) child->prev->next = w; else cur->first = w;
        cur->last = w;
        child->prev = child->next = NULL;
        child->parent = w;
        w->first = w->last = child;
        return w;
    }

    /* The view a flag modifier (resizable, lineLimit) is meant for: look through wrappers. */
    static wui_node *innermost(wui_node *n) {
        while (n && n->first && n->kind != K_STACK && n->kind != K_BUTTON) n = n->first;
        return n;
    }

    void wui_padding(float t, float r, float b, float l) { wui_node *w = wrap(K_PADDING); if (w) { w->a[0] = t; w->a[1] = r; w->a[2] = b; w->a[3] = l; } }
    void wui_frame(float fw, float fh, float minw, float maxw, float minh, float maxh, int align) {
        wui_node *w = wrap(K_FRAME);
        if (w) { w->a[0] = fw; w->a[1] = fh; w->a[2] = minw; w->a[3] = maxw; w->a[4] = minh; w->a[5] = maxh; w->i[1] = align; }
    }
    void wui_background(int r, int g, int b, int a) { wui_node *w = wrap(K_BACKGROUND); if (w) { w->c[0] = r; w->c[1] = g; w->c[2] = b; w->c[3] = a; } }
    void wui_foreground(int r, int g, int b, int a) { wui_node *w = wrap(K_FOREGROUND); if (w) { w->c[0] = r; w->c[1] = g; w->c[2] = b; w->c[3] = a; } }
    void wui_font(int size, int bold) { wui_node *w = wrap(K_FONT); if (w) { w->i[0] = size; w->i[1] = bold; } }
    void wui_opacity(float o) { wui_node *w = wrap(K_OPACITY); if (w) w->a[0] = o; }
    void wui_offset(float x, float y) { wui_node *w = wrap(K_OFFSET); if (w) { w->a[0] = x; w->a[1] = y; } }
    void wui_corner(float r) { wui_node *w = wrap(K_CORNER); if (w) w->a[0] = r; }
    void wui_border(int r, int g, int b, int a, float width) { wui_node *w = wrap(K_BORDER); if (w) { w->c[0] = r; w->c[1] = g; w->c[2] = b; w->c[3] = a; w->a[0] = width; } }
    void wui_long_press(void (*action)(void *), void *ctx, int frames) {
        wui_node *w = wrap(K_TAP);
        if (w) { w->action = action; w->ctx = ctx; w->interactive = 1; w->i[3] = frames > 0 ? frames : 1; }
    }
    void wui_underline(void) { wui_node *w = wrap(K_FONT); if (w) w->i[2] = 1; }
    void wui_overlay(int r, int g, int b, int a) { wui_node *w = wrap(K_BACKGROUND); if (w) { w->i[0] = 1; w->c[0] = r; w->c[1] = g; w->c[2] = b; w->c[3] = a; } }
    void wui_shadow(int r, int g, int b, int a, float dx, float dy) { wui_node *w = wrap(K_BACKGROUND); if (w) { w->i[0] = 2; w->c[0] = r; w->c[1] = g; w->c[2] = b; w->c[3] = a; w->a[0] = dx; w->a[1] = dy; } }
    void wui_position(float x, float y) { wui_node *w = wrap(K_OFFSET); if (w) { w->i[0] = 1; w->a[0] = x; w->a[1] = y; } }
    void wui_on_tap(void (*action)(void *), void *ctx) { wui_node *w = wrap(K_TAP); if (w) { w->action = action; w->ctx = ctx; w->interactive = 1; } }
    void wui_disabled(int d) {
        wui_node *n = cur->last;
        if (!n) return;
        n->disabled = d != 0;
        for (wui_node *k = n; k; k = k->first) { if (k->interactive) k->disabled = d != 0; if (k->kind == K_STACK) break; }
    }
    void wui_resizable(int fit) { wui_node *n = innermost(cur->last); if (n && n->kind == K_IMAGE) { n->i[1] = 1; n->i[2] = fit; } }
    void wui_line_limit(int lines) { wui_node *n = innermost(cur->last); if (n && n->kind == K_TEXT) n->i[2] = lines > 0 ? lines : 0; }
    void wui_button_plain(void) { wui_node *n = cur->last; if (n && n->kind == K_BUTTON) n->i[0] = 1; }

    /* ---- text ---- */
    #define MAX_LINES 24
    typedef struct { int start[MAX_LINES], len[MAX_LINES]; int count; float width; } lines_t;

    static float span_width(int font, const char *text, int start, int len) {
        char buf[160];
        if (len > 159) len = 159;
        if (len < 0) len = 0;
        memcpy(buf, text + start, (size_t)len);
        buf[len] = 0;
        return (float)wiiui_text_width(font, buf);
    }

    /* Breaks `text` at spaces to fit `maxw` (one line when maxw is huge or the limit is 1). */
    static void break_lines(int font, const char *text, float maxw, int limit, lines_t *out) {
        out->count = 0; out->width = 0;
        int n = (int)strlen(text), pos = 0;
        int wrap = limit != 1 && maxw < WUI_INF;
        while (out->count < MAX_LINES) {
            int line_start = pos, i = pos, last_space = -1, end, next;
            for (;;) {
                if (i >= n || text[i] == '\n') { end = i; next = i < n ? i + 1 : n + 1; break; }
                if (text[i] == ' ') last_space = i;
                if (wrap && i > line_start && span_width(font, text, line_start, i - line_start + 1) > maxw) {
                    if (last_space > line_start) { end = last_space; next = last_space + 1; }
                    else { end = i; next = i; }
                    break;
                }
                i++;
            }
            out->start[out->count] = line_start;
            out->len[out->count] = end - line_start;
            float w = span_width(font, text, line_start, end - line_start);
            if (w > out->width) out->width = w;
            out->count++;
            pos = next;
            if (pos > n) break;
            if (limit > 0 && out->count >= limit) break;
        }
        if (out->count == 0) { out->count = 1; out->start[0] = 0; out->len[0] = 0; }
    }

    /* ---- layout ---- */
    typedef struct { float w, h; unsigned char fw, fh; } msize;

    static style child_style(const wui_node *n, style st) {
        switch (n->kind) {
        case K_FOREGROUND: st.fg[0] = n->c[0]; st.fg[1] = n->c[1]; st.fg[2] = n->c[2]; st.fg[3] = n->c[3]; break;
        case K_FONT:
            if (n->i[0] > 0) { st.font = n->i[0]; st.bold = n->i[1]; } else if (n->i[1]) st.bold = 1;
            if (n->i[2]) st.underline = 1;
            break;
        case K_OPACITY: st.opacity *= n->a[0]; break;
        case K_CORNER: st.corner = n->a[0]; break;
        case K_BUTTON:
            if (!n->i[0]) { st.fg[0] = st.fg[1] = st.fg[2] = 255; st.fg[3] = 255; }
            break;
        default: break;
        }
        return st;
    }

    static msize measure(wui_node *n, float pw, float ph, style st);

    static msize measure_cached(wui_node *n, float pw, float ph, style st) {
        if (n->cvalid && n->cpw == pw && n->cph == ph) { msize m = { n->cw, n->ch, n->cflexw, n->cflexh }; return m; }
        msize m = measure(n, pw, ph, st);
        n->cpw = pw; n->cph = ph; n->cw = m.w; n->ch = m.h; n->cflexw = m.fw; n->cflexh = m.fh; n->cvalid = 1;
        return m;
    }

    static msize measure_stack(wui_node *n, float pw, float ph, style st) {
        int axis = n->i[0];
        float spacing = n->a[0];
        msize out = { 0, 0, 0, 0 };
        if (axis == 2) {
            for (wui_node *c = n->first; c; c = c->next) {
                msize m = measure_cached(c, pw, ph, st);
                c->w = m.w; c->h = m.h;
                out.w = fmax2(out.w, m.w); out.h = fmax2(out.h, m.h);
                out.fw |= m.fw; out.fh |= m.fh;
            }
            return out;
        }
        int vertical = axis == 0;
        float main_p = vertical ? ph : pw, cross_p = vertical ? pw : ph;
        int count = 0, flex = 0;
        for (wui_node *c = n->first; c; c = c->next) count++;
        float fixed = count > 1 ? spacing * (count - 1) : 0;
        /* 1. ideal sizes with an open main axis */
        for (wui_node *c = n->first; c; c = c->next) {
            msize m = measure_cached(c, vertical ? cross_p : WUI_INF, vertical ? WUI_INF : cross_p, st);
            int fm = vertical ? m.fh : m.fw;
            float im = vertical ? m.h : m.w;
            c->ideal = im;
            if (fm) flex++; else fixed += im;
            c->flexmain = fm;
        }
        float flex_min = 0;
        for (wui_node *c = n->first; c; c = c->next) if (c->flexmain) flex_min += c->ideal;
        float share = (main_p < WUI_INF && flex > 0) ? fmax2(0, main_p - fixed - flex_min) / flex : 0;
        /* 2. final main sizes, then re-measure with them */
        float total = count > 1 ? spacing * (count - 1) : 0, cross = 0;
        int cross_flex = 0;
        for (wui_node *c = n->first; c; c = c->next) {
            float fm = c->flexmain ? c->ideal + share : c->ideal;
            msize m = measure_cached(c, vertical ? cross_p : fm, vertical ? fm : cross_p, st);
            float actual_main = vertical ? m.h : m.w;
            float actual_cross = vertical ? m.w : m.h;
            if (c->flexmain && main_p < WUI_INF) actual_main = fm;
            c->w = vertical ? m.w : actual_main;
            c->h = vertical ? actual_main : m.h;
            total += actual_main;
            cross = fmax2(cross, actual_cross);
            if (vertical ? m.fw : m.fh) cross_flex = 1;
        }
        if (cross_flex && cross_p < WUI_INF) cross = cross_p;
        out.w = vertical ? cross : total; out.h = vertical ? total : cross;
        out.fw = vertical ? (unsigned char)cross_flex : (unsigned char)(flex > 0);
        out.fh = vertical ? (unsigned char)(flex > 0) : (unsigned char)cross_flex;
        return out;
    }

    static msize measure(wui_node *n, float pw, float ph, style st) {
        msize m = { 0, 0, 0, 0 };
        style cs = child_style(n, st);
        switch (n->kind) {
        case K_TEXT: {
            int font = st.font;
            lines_t ln; break_lines(font, n->text, pw, n->i[2], &ln);
            int lh = wiiui_font_height(font);
            m.w = ln.width; m.h = (float)(lh * ln.count);
            return m;
        }
        case K_IMAGE: {
            float iw = (float)wiiui_sprite_width(n->i[0]), ih = (float)wiiui_sprite_height(n->i[0]);
            if (!n->i[1]) { m.w = iw; m.h = ih; return m; }
            m.fw = m.fh = 1;
            if (n->i[2] && iw > 0 && ih > 0) {          /* scaledToFit */
                float sw = pw < WUI_INF ? pw : iw, sh = ph < WUI_INF ? ph : ih;
                float k = fmin2(sw / iw, sh / ih);
                m.w = iw * k; m.h = ih * k; return m;
            }
            m.w = pw < WUI_INF ? pw : iw; m.h = ph < WUI_INF ? ph : ih; return m;
        }
        case K_SPACER: m.fw = m.fh = 1; return m;
        case K_DIVIDER: m.fw = 1; m.w = pw < WUI_INF ? pw : 10; m.h = 1; return m;
        case K_SHAPE: case K_COLOR:
            m.fw = m.fh = 1; m.w = pw < WUI_INF ? pw : 10; m.h = ph < WUI_INF ? ph : 10; return m;
        case K_STACK: return measure_stack(n, pw, ph, cs);
        case K_PADDING: {
            float hp = n->a[1] + n->a[3], vp = n->a[0] + n->a[2];
            msize c = n->first ? measure_cached(n->first, pw < WUI_INF ? fmax2(0, pw - hp) : pw, ph < WUI_INF ? fmax2(0, ph - vp) : ph, cs) : m;
            if (n->first) { n->first->w = c.w; n->first->h = c.h; }
            m.w = c.w + hp; m.h = c.h + vp; m.fw = c.fw; m.fh = c.fh; return m;
        }
        case K_FRAME: {
            float fw = n->a[0], fh = n->a[1], minw = n->a[2], maxw = n->a[3], minh = n->a[4], maxh = n->a[5];
            float cw = fw >= 0 ? fw : (maxw >= 0 ? (maxw >= WUI_INF ? pw : fmin2(pw, maxw)) : pw);
            float chh = fh >= 0 ? fh : (maxh >= 0 ? (maxh >= WUI_INF ? ph : fmin2(ph, maxh)) : ph);
            if (minw >= 0 && cw < minw) cw = minw;
            if (minh >= 0 && chh < minh) chh = minh;
            msize c = n->first ? measure_cached(n->first, cw, chh, cs) : m;
            if (n->first) { n->first->w = c.w; n->first->h = c.h; }
            float w, h;
            if (fw >= 0) w = fw;
            else if (maxw >= WUI_INF) { w = pw < WUI_INF ? pw : c.w; m.fw = 1; }
            else if (maxw >= 0) w = clampf(c.w, minw >= 0 ? minw : 0, maxw);
            else w = minw >= 0 ? fmax2(c.w, minw) : c.w;
            if (fh >= 0) h = fh;
            else if (maxh >= WUI_INF) { h = ph < WUI_INF ? ph : c.h; m.fh = 1; }
            else if (maxh >= 0) h = clampf(c.h, minh >= 0 ? minh : 0, maxh);
            else h = minh >= 0 ? fmax2(c.h, minh) : c.h;
            if (fw < 0 && maxw < 0 && minw < 0) m.fw = c.fw;
            if (fh < 0 && maxh < 0 && minh < 0) m.fh = c.fh;
            m.w = w; m.h = h; return m;
        }
        case K_BUTTON:
            if (!n->i[0]) {                                     /* default style: padded label */
                msize c = n->first ? measure_cached(n->first, pw < WUI_INF ? fmax2(0, pw - 28) : pw, ph < WUI_INF ? fmax2(0, ph - 16) : ph, cs) : m;
                if (n->first) { n->first->w = c.w; n->first->h = c.h; }
                m.w = c.w + 28; m.h = c.h + 16; return m;
            }
            /* plain buttons size like their label */
            __attribute__((fallthrough));
        case K_BACKGROUND: case K_FOREGROUND: case K_FONT: case K_OPACITY: case K_OFFSET: case K_CORNER: case K_BORDER: case K_TAP: {
            msize c = n->first ? measure_cached(n->first, pw, ph, cs) : m;
            if (n->first) { n->first->w = c.w; n->first->h = c.h; }
            return c;
        }
        case K_TOGGLE: {
            float natural = (float)wiiui_text_width(st.font, n->text) + 16 + 56;
            m.fw = 1; m.w = pw < WUI_INF ? fmax2(pw, natural) : natural; m.h = fmax2(34, (float)wiiui_font_height(st.font)); return m;
        }
        case K_SLIDER: m.fw = 1; m.w = pw < WUI_INF ? pw : 160; m.h = 30; return m;
        case K_PROGRESS: m.fw = 1; m.w = pw < WUI_INF ? pw : 160; m.h = 10; return m;
        }
        return m;
    }

    static float align_h(int code) { return (code % 3) * 0.5f; }
    static float align_v(int code) { return (code / 3) * 0.5f; }

    /* Gives `n` its final rectangle and places its children inside it. */
    static void arrange(wui_node *n, float x, float y, float w, float h, style st) {
        n->x = x; n->y = y; n->w = w; n->h = h;
        style cs = child_style(n, st);
        msize m = measure_cached(n, w, h, st);     /* children now hold sizes for this exact proposal */
        (void)m;
        switch (n->kind) {
        case K_STACK: {
            int axis = n->i[0], align = n->i[1];
            if (axis == 2) {
                for (wui_node *c = n->first; c; c = c->next)
                    arrange(c, (w - c->w) * align_h(align), (h - c->h) * align_v(align), c->w, c->h, cs);
                break;
            }
            int vertical = axis == 0;
            float spacing = n->a[0];
            float pos = 0;       /* content starts at the top/left; the stack is sized to it */
            for (wui_node *c = n->first; c; c = c->next) {
                float cross_box = vertical ? w : h, cross_size = vertical ? c->w : c->h;
                float f = vertical ? align_h(align) : align_v(align);
                float cross_off = (cross_box - cross_size) * f;
                if (vertical) arrange(c, cross_off, pos, c->w, c->h, cs); else arrange(c, pos, cross_off, c->w, c->h, cs);
                pos += (vertical ? c->h : c->w) + spacing;
            }
            break;
        }
        case K_PADDING:
            if (n->first) arrange(n->first, n->a[3], n->a[0], n->first->w, n->first->h, cs);
            break;
        case K_FRAME:
            if (n->first) {
                int align = n->i[1];
                arrange(n->first, (w - n->first->w) * align_h(align), (h - n->first->h) * align_v(align), n->first->w, n->first->h, cs);
            }
            break;
        case K_BUTTON:
            if (n->first) {
                if (!n->i[0]) arrange(n->first, 14, 8, n->first->w, n->first->h, cs);
                else arrange(n->first, 0, 0, n->first->w, n->first->h, cs);
            }
            break;
        case K_BACKGROUND: case K_FOREGROUND: case K_FONT: case K_OPACITY: case K_OFFSET: case K_CORNER: case K_BORDER: case K_TAP:
            if (n->first) arrange(n->first, 0, 0, w, h, cs);
            break;
        default: break;
        }
    }

    /* ---- interaction ---- */
    #define MAX_INTERACTIVE 96
    typedef struct { wui_node *n; float x, y, w, h; } iarea;
    static iarea areas[MAX_INTERACTIVE];
    static int area_count;

    static void collect(wui_node *n, float ox, float oy) {
        float ax = ox + n->x, ay = oy + n->y;
        if (n->kind == K_OFFSET) { if (n->i[0]) { ax = ox + n->a[0] - n->w / 2; ay = oy + n->a[1] - n->h / 2; } else { ax += n->a[0]; ay += n->a[1]; } }
        if (n->interactive && area_count < MAX_INTERACTIVE) {
            iarea *a = &areas[area_count++];
            a->n = n; a->x = ax; a->y = ay; a->w = n->w; a->h = n->h;
        }
        for (wui_node *c = n->first; c; c = c->next) collect(c, ax, ay);
    }

    static int inside(const iarea *a, int px, int py) { return px >= a->x && px < a->x + a->w && py >= a->y && py < a->y + a->h; }

    static void move_focus(int dx, int dy) {
        if (area_count == 0) return;
        if (focus >= area_count) focus = 0;
        float cx = areas[focus].x + areas[focus].w / 2, cy = areas[focus].y + areas[focus].h / 2;
        int best = -1; float best_score = 1e30f;
        for (int i = 0; i < area_count; i++) {
            if (i == focus || areas[i].n->disabled) continue;
            float ex = areas[i].x + areas[i].w / 2 - cx, ey = areas[i].y + areas[i].h / 2 - cy;
            float along = dx ? ex * dx : ey * dy, across = dx ? ey : ex;
            if (along <= 0.5f) continue;
            float score = along + 2.0f * fabsf(across);
            if (score < best_score) { best_score = score; best = i; }
        }
        if (best >= 0) focus = best;
    }

    static void handle_input(void) {
        area_count = 0;
        collect(root, 0, 0);
        int px = 0, py = 0;
        int pointer = wiiui_pointer(&px, &py);
        if (pointer && (fabsf((float)px - last_px) > 3 || fabsf((float)py - last_py) > 3)) controller = 0;
        last_px = (float)px; last_py = (float)py;
        hot = NULL;
        if (pointer && !controller) for (int i = area_count - 1; i >= 0; i--) if (!areas[i].n->disabled && inside(&areas[i], px, py)) { hot = areas[i].n; break; }
        if (focus >= area_count) focus = 0;
        unsigned pr = wiiui_pressed(0), held = wiiui_held(0);
        wui_node *fn = area_count ? areas[focus].n : NULL;
        int dpad = pr & (WPAD_BUTTON_UP | WPAD_BUTTON_DOWN | WPAD_BUTTON_LEFT | WPAD_BUTTON_RIGHT);
        if (dpad) {
            if (!controller) { controller = 1; if (hot) for (int i = 0; i < area_count; i++) if (areas[i].n == hot) focus = i; }
            else if (fn && fn->kind == K_SLIDER && (pr & (WPAD_BUTTON_LEFT | WPAD_BUTTON_RIGHT))) {
                double step = (fn->hi - fn->lo) / 20.0;
                *fn->dval = fmin(fn->hi, fmax(fn->lo, *fn->dval + ((pr & WPAD_BUTTON_RIGHT) ? step : -step)));
            } else {
                if (pr & WPAD_BUTTON_UP) move_focus(0, -1);
                if (pr & WPAD_BUTTON_DOWN) move_focus(0, 1);
                if (pr & WPAD_BUTTON_LEFT) move_focus(-1, 0);
                if (pr & WPAD_BUTTON_RIGHT) move_focus(1, 0);
            }
            fn = area_count ? areas[focus].n : NULL;
        }
        wui_node *target = controller ? fn : hot;
        pressed_node = NULL;
        if (target && (held & WPAD_BUTTON_A)) pressed_node = target;
        if (target && target->kind == K_TAP && target->i[3] > 0) {      /* long press: fires once, when held long enough */
            if (held & WPAD_BUTTON_A) {
                if (hold_node != target) { hold_node = target; hold_frames = 0; }
                if (++hold_frames == target->i[3] && !target->disabled && target->action) target->action(target->ctx);
            } else hold_node = NULL;
        } else hold_node = NULL;
        if (target && (pr & WPAD_BUTTON_A) && !target->disabled) {
            if (target->kind == K_TOGGLE) *target->flag = !*target->flag;
            else if (target->action && !(target->kind == K_TAP && target->i[3] > 0)) target->action(target->ctx);
        }
        /* dragging a slider with the pointer */
        if (!controller && hot && hot->kind == K_SLIDER && (held & WPAD_BUTTON_A)) {
            for (int i = 0; i < area_count; i++) if (areas[i].n == hot) {
                float k = clampf(((float)px - areas[i].x - 10) / fmaxf(1, areas[i].w - 20), 0, 1);
                *hot->dval = hot->lo + (hot->hi - hot->lo) * k;
            }
        }
    }

    /* ---- drawing ---- */
    static wgfx_texture circle_tex;
    static unsigned char circle_data[64 * 64 * 2] __attribute__((aligned(32)));
    static int circle_ready = 0;

    static void make_circle(void) {
        for (int y = 0; y < 64; y++) for (int x = 0; x < 64; x++) {
            float dx = x + 0.5f - 32, dy = y + 0.5f - 32;
            float cov = clampf(32.0f - sqrtf(dx * dx + dy * dy) + 0.5f, 0, 1);
            int off = (((y / 4) * 16 + (x / 4)) * 16 + (y % 4) * 4 + (x % 4)) * 2;
            circle_data[off] = (unsigned char)(cov * 255); circle_data[off + 1] = 255;
        }
        circle_tex.data = circle_data; circle_tex.w = circle_tex.h = circle_tex.pw = circle_tex.ph = 64;
        circle_tex.format = WGFX_IA8; circle_tex.smooth = 1;
        circle_ready = 1;
    }

    static int alpha_of(unsigned char a, float opacity) { return (int)(a * opacity); }

    static void fill_round(float x, float y, float w, float h, float r, const unsigned char *c, int a) {
        if (a <= 0 || w <= 0 || h <= 0) return;
        /* Whole-pixel edges, so the pieces meet exactly. */
        int x0 = (int)(x + 0.5f), y0 = (int)(y + 0.5f), x1 = (int)(x + w + 0.5f), y1 = (int)(y + h + 0.5f);
        int iw = x1 - x0, ih = y1 - y0;
        if (iw <= 0 || ih <= 0) return;
        int m = (iw < ih ? iw : ih) / 2;
        int ir = r > 1e8f ? m : (int)(r + 0.5f);
        if (ir > m) ir = m;
        if (ir < 1) { wiiui_draw_rect(x0, y0, iw, ih, c[0], c[1], c[2], a); return; }
        if (!circle_ready) make_circle();
        wiiui_draw_rect(x0 + ir, y0, iw - 2 * ir, ih, c[0], c[1], c[2], a);
        wiiui_draw_rect(x0, y0 + ir, ir, ih - 2 * ir, c[0], c[1], c[2], a);
        wiiui_draw_rect(x1 - ir, y0 + ir, ir, ih - 2 * ir, c[0], c[1], c[2], a);
        wgfx_quad(&circle_tex, (float)x0, (float)y0, (float)ir, (float)ir, 0, 0, 0.5f, 0.5f, c[0], c[1], c[2], a);
        wgfx_quad(&circle_tex, (float)(x1 - ir), (float)y0, (float)ir, (float)ir, 0.5f, 0, 1, 0.5f, c[0], c[1], c[2], a);
        wgfx_quad(&circle_tex, (float)x0, (float)(y1 - ir), (float)ir, (float)ir, 0, 0.5f, 0.5f, 1, c[0], c[1], c[2], a);
        wgfx_quad(&circle_tex, (float)(x1 - ir), (float)(y1 - ir), (float)ir, (float)ir, 0.5f, 0.5f, 1, 1, c[0], c[1], c[2], a);
    }

    static void fill_circle(float x, float y, float w, float h, const unsigned char *c, int a) {
        if (a <= 0) return;
        if (!circle_ready) make_circle();
        wgfx_quad(&circle_tex, x, y, w, h, 0, 0, 1, 1, c[0], c[1], c[2], a);
    }

    static unsigned char lighter(int v, int d) { v += d; return (unsigned char)(v < 0 ? 0 : v > 255 ? 255 : v); }

    static void draw(wui_node *n, float ox, float oy, style st) {
        float ax = ox + n->x, ay = oy + n->y;
        if (n->kind == K_OFFSET) { if (n->i[0]) { ax = ox + n->a[0] - n->w / 2; ay = oy + n->a[1] - n->h / 2; } else { ax += n->a[0]; ay += n->a[1]; } }
        style cs = child_style(n, st);
        int focused = controller && area_count && areas[focus].n == n;
        switch (n->kind) {
        case K_TEXT: {
            lines_t ln; break_lines(st.font, n->text, n->w + 0.5f, n->i[2], &ln);
            int lh = wiiui_font_height(st.font);
            for (int i = 0; i < ln.count; i++) {
                char buf[160]; int l = ln.len[i]; if (l > 159) l = 159;
                memcpy(buf, n->text + ln.start[i], (size_t)l); buf[l] = 0;
                wiiui_draw_text(st.font, (int)ax, (int)(ay + i * lh), buf, st.fg[0], st.fg[1], st.fg[2], alpha_of(st.fg[3], st.opacity));
                if (st.underline) wiiui_draw_rect((int)ax, (int)(ay + i * lh + lh - 2), wiiui_text_width(st.font, buf), 1, st.fg[0], st.fg[1], st.fg[2], alpha_of(st.fg[3], st.opacity));
            }
            break;
        }
        case K_IMAGE:
            wiiui_draw_sprite_ex(n->i[0], (int)ax, (int)ay, (int)n->w, (int)n->h, 0, 0, alpha_of(255, st.opacity));
            break;
        case K_DIVIDER: {
            unsigned char c[3] = { 150, 150, 150 };
            wiiui_draw_rect((int)ax, (int)ay, (int)n->w, 1, c[0], c[1], c[2], alpha_of(160, st.opacity));
            break;
        }
        case K_SHAPE:
            if (n->i[0] == 2) fill_circle(ax, ay, n->w, n->h, st.fg, alpha_of(st.fg[3], st.opacity));
            else fill_round(ax, ay, n->w, n->h, n->i[0] == 3 ? 1e9f : (n->i[0] == 1 ? n->a[0] : 0), st.fg, alpha_of(st.fg[3], st.opacity));
            break;
        case K_COLOR: fill_round(ax, ay, n->w, n->h, st.corner, n->c, alpha_of(n->c[3], st.opacity)); break;
        case K_BACKGROUND:
            if (n->i[0] == 0) fill_round(ax, ay, n->w, n->h, st.corner, n->c, alpha_of(n->c[3], st.opacity));
            else if (n->i[0] == 2) fill_round(ax + n->a[0], ay + n->a[1], n->w, n->h, st.corner, n->c, alpha_of(n->c[3], st.opacity));      /* shadow */
            break;
        case K_BUTTON:
            if (!n->i[0]) {
                int d = n->disabled ? 0 : (pressed_node == n ? -40 : (hot == n || focused ? 30 : 0));
                unsigned char fill[3] = { lighter(10, d), lighter(110, d), lighter(240, d) };
                if (n->disabled) { fill[0] = 90; fill[1] = 90; fill[2] = 100; }
                fill_round(ax, ay, n->w, n->h, 10, fill, alpha_of(255, st.opacity));
            }
            break;
        case K_TOGGLE: {
            wiiui_draw_text(st.font, (int)ax, (int)(ay + (n->h - wiiui_font_height(st.font)) / 2), n->text, st.fg[0], st.fg[1], st.fg[2], alpha_of(st.fg[3], st.opacity));
            float tx = ax + n->w - 56, ty = ay + (n->h - 30) / 2;
            unsigned char track_on[3] = { 52, 199, 89 }, track_off[3] = { 120, 120, 128 }, white[3] = { 255, 255, 255 };
            fill_round(tx, ty, 56, 30, 15, *n->flag ? track_on : track_off, alpha_of(255, st.opacity));
            fill_circle(tx + (*n->flag ? 56 - 27 : 3), ty + 3, 24, 24, white, alpha_of(255, st.opacity));
            break;
        }
        case K_SLIDER: {
            unsigned char track[3] = { 110, 110, 120 }, fill[3] = { 10, 132, 255 }, white[3] = { 255, 255, 255 };
            float k = n->hi > n->lo ? (float)((*n->dval - n->lo) / (n->hi - n->lo)) : 0;
            k = clampf(k, 0, 1);
            fill_round(ax + 10, ay + n->h / 2 - 3, n->w - 20, 6, 3, track, alpha_of(255, st.opacity));
            fill_round(ax + 10, ay + n->h / 2 - 3, (n->w - 20) * k, 6, 3, fill, alpha_of(255, st.opacity));
            fill_circle(ax + 10 + (n->w - 20) * k - 12, ay + n->h / 2 - 12, 24, 24, white, alpha_of(255, st.opacity));
            break;
        }
        case K_PROGRESS: {
            unsigned char track[3] = { 90, 90, 100 }, fill[3] = { 10, 132, 255 };
            float k = clampf((float)n->lo, 0, 1);
            fill_round(ax, ay, n->w, n->h, 5, track, alpha_of(255, st.opacity));
            fill_round(ax, ay, n->w * k, n->h, 5, fill, alpha_of(255, st.opacity));
            break;
        }
        default: break;
        }
        for (wui_node *c = n->first; c; c = c->next) draw(c, ax, ay, cs);
        if (n->kind == K_BACKGROUND && n->i[0] == 1) fill_round(ax, ay, n->w, n->h, st.corner, n->c, alpha_of(n->c[3], st.opacity));      /* overlay */
        if (n->kind == K_BORDER) {
            float bw = n->a[0] < 1 ? 1 : n->a[0];
            int a = alpha_of(n->c[3], st.opacity);
            wiiui_draw_rect((int)ax, (int)ay, (int)n->w, (int)bw, n->c[0], n->c[1], n->c[2], a);
            wiiui_draw_rect((int)ax, (int)(ay + n->h - bw), (int)n->w, (int)bw, n->c[0], n->c[1], n->c[2], a);
            wiiui_draw_rect((int)ax, (int)ay, (int)bw, (int)n->h, n->c[0], n->c[1], n->c[2], a);
            wiiui_draw_rect((int)(ax + n->w - bw), (int)ay, (int)bw, (int)n->h, n->c[0], n->c[1], n->c[2], a);
        }
        if (focused) {                                       /* controller focus ring */
            wiiui_draw_rect((int)ax - 3, (int)ay - 3, (int)n->w + 6, 3, 255, 214, 10, 255);
            wiiui_draw_rect((int)ax - 3, (int)(ay + n->h), (int)n->w + 6, 3, 255, 214, 10, 255);
            wiiui_draw_rect((int)ax - 3, (int)ay, 3, (int)n->h, 255, 214, 10, 255);
            wiiui_draw_rect((int)(ax + n->w), (int)ay, 3, (int)n->h, 255, 214, 10, 255);
        }
    }

    void wui_finish(void) {
        style st = { 24, 0, { 255, 255, 255, 255 }, 1.0f, 0, 0 };
        arrange(root, 0, 0, wiiui_screen_w, 480, st);      /* the screen is the root's size; its content is centred */
        handle_input();
        draw(root, 0, 0, st);
    }
    """#
}
